def solve(data: dict) -> bool:
    total_sum = sum(data['nums'])
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2

    n = len(data['nums'])

    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]

    # Base case: there's always a subset that sums to 0 (empty set)
    dp[0][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(target_sum + 1):
            if data['nums'][i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - data['nums'][i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target_sum]

