def solve(data):
    text = data['text']

    # Edge case: empty or minimal inputs
    if not text:
        return True

    # Initialize stack for tracking opening brackets
    stack = []

    # Mapping of closing brackets to their corresponding opening brackets
    bracket_pairs = {')': '(', ']': '[', '}': '{'}

    # Iterate through each character in the text
    for char in text:
        # If the character is an opening bracket, push it onto the stack
        if char in bracket_pairs.values():
            stack.append(char)
        # If the character is a closing bracket
        elif char in bracket_pairs:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening bracket, return False
            if not stack or stack.pop() != bracket_pairs[char]:
                return False

    # If the stack is empty at the end, all brackets were matched correctly
    return len(stack) == 0

