def solve(data: dict) -> int:
    grid = data['grid']

    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == 1:
            return float('inf')

        if i == m - 1 and j == n - 1:
            return 0

        grid[i][j] = 1  # Mark cell as visited

        up = dfs(i - 1, j)
        down = dfs(i + 1, j)
        left = dfs(i, j - 1)
        right = dfs(i, j + 1)

        grid[i][j] = 0  # Reset cell status

        return min(up, down, left, right) + 1

    result = dfs(0, 0)
    return result if result != float('inf') else -1

