    # Initialize an empty stack
    stack = []

    # Iterate through each character in the input string
    for char in text:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top = stack.pop()
            if (char == ")" and top != "(") or (char == "]" and top != "[") or (char == "}" and top != "{"):
