    return list(anagram_groups.values())

def solve(data):
    capacity = data["capacity"]
    ops = data["ops"]

    # Initialize an empty dictionary and a list to keep track of the order
    cache = {}
    order = []

    result = []

    for op in ops:
        if op[0] == "put":
            key, value = op[1:]

            if key in cache:
                # Update existing key
                order.remove(key)
                order.append(key)
                cache[key] = value
            else:
                # Add new key-value pair
                order.append(key)
                cache[key] = value

                # Ensure capacity limit
                if len(order) > capacity:
                    del cache[order.pop(0)]

        elif op[0] == "get":
            key = op[1]
            if key in cache:
                # Move to the end of the list
                order.remove(key)
                order.append(key)
                result.append(cache[key])
            else:
                result.append(-1)

    return result

